<script lang="ts">import{onMount}from'svelte';import{csrfHeaders,idempotencyKey}from'$lib/api/client';import{productLabel}from'$lib/product-language';let orgID='',profile:any={},permissions:any={},method='split_settlement',reference='',cycle='per_settlement',message='',busy=false;async function load(){const r=await fetch('/api/v1/organizations',{credentials:'include'});const d=await r.json();orgID=d.organizations?.[0]?.id??'';if(!orgID)return;const q=await fetch(`/api/v1/organizations/${orgID}/onboarding`,{credentials:'include'});const x=await q.json();profile=x.profile??{};permissions=x.permissions??{};method=profile.billing_method||method;cycle=profile.billing_cycle||cycle}async function save(){busy=true;const r=await fetch(`/api/v1/organizations/${orgID}/onboarding/billing`,{method:'PUT',credentials:'include',headers:{'Content-Type':'application/json','Idempotency-Key':idempotencyKey(),...csrfHeaders()},body:JSON.stringify({expected_version:profile.version,method,provider_reference:reference,cycle})});const d=await r.json().catch(()=>({}));busy=false;message=r.ok?'How you pay Kredit fees was saved.':'We could not save this: '+(d.detail??'try again.');if(r.ok)profile=d.profile}onMount(load);</script>
<svelte:head><title>Kredit fees — Kredit</title></svelte:head><main class="shell workspace form-page"><p class="eyebrow">Settings / Kredit fees</p><h1>How should Kredit take its fee?</h1><p class="lede">Choose the easiest way for your business. You will always see the fee before money moves.</p>{#if message}<p class="notice">{message}</p>{/if}<section class="card"><header><h2>Paying Kredit</h2><span>{productLabel(profile.billing_state,'Not started')}</span></header>{#if permissions.billing}<label>How should we take the fee?<select bind:value={method}><option value="split_settlement">Take it when customer money enters</option><option value="authorized_debit">Debit it from my business account</option><option value="consolidated_invoice">Send my business one bill</option></select></label><label>Payment setup number<input bind:value={reference} autocomplete="off" /><small>Your payment company gives you this number.</small></label><label>How often?<select bind:value={cycle}><option value="per_settlement">After each payment</option><option value="weekly">Once a week</option><option value="monthly">Once a month</option></select></label><aside><strong>What Kredit charges</strong><p>We take 0.5% when your customer pays. We take 1% only when Kredit collects late money for you.</p></aside><button disabled={busy||!reference} onclick={save}>{busy?'Saving…':'Save how I will pay'}</button>{:else}<p>You can see this setting, but only the owner or a person allowed to handle money can change it.</p>{/if}</section><a href="/app/settings">← All settings</a></main>
<style>.form-page{max-width:52rem}.form-page h1{font-size:clamp(2.4rem,6vw,4.5rem);line-height:1}.card{display:grid;gap:.8rem;padding:1.4rem;border:1px solid var(--color-border);border-radius:1rem;background:var(--color-surface)}header{display:flex;justify-content:space-between}.card label{display:grid;gap:.3rem;font-weight:700}.card input,.card select,.card button{padding:.75rem;border:1px solid var(--color-border);border-radius:.65rem;font:inherit}.card button{background:var(--color-primary);color:white;font-weight:800}aside,.notice{padding:1rem;background:#eef5ff;border-radius:.7rem}aside p{margin:.3rem 0}</style>
